    Personel = apps.get_model('panel', 'Personel')
    MutfakZayi = apps.get_model('panel', 'MutfakZayi')
    idler = set()
    idler.update(Vardiya.objects.filter(vardiya_tipi='Mutfak Görevi', atanan_sube__isnull=False)
                 .values_list('atanan_sube_id', flat=True))
    idler.update(MutfakZayi.objects.filter(sube__isnull=False).values_list('sube_id', flat=True))
    idler.update(Personel.objects.filter(rol='Mutfak Personeli', sube__isnull=False)
                 .values_list('sube_id', flat=True))
    if idler:
        Sube.objects.filter(id__in=idler, depo_mu=False).update(mutfak_var=True)


